{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR_FAILED_ACTION",
      "definition": "A subsequent agent action modifies the command or approach of an earlier tool call whose observation reported an execution error, in order to accomplish the intended operation.",
      "source_description": "An earlier tool call whose observation reports an execution error, invalid invocation, or otherwise failed operation.",
      "target_description": "A subsequent agent action that corrects the command or approach to accomplish the same intended operation."
    },
    {
      "name": "PROVISIONS_MISSING_PREREQUISITE",
      "definition": "An agent action installs or provisions a tool, package, or capability whose absence in the execution environment was revealed by an earlier inspection.",
      "source_description": "An earlier observation revealing that a required tool, package, or capability is unavailable in the environment.",
      "target_description": "A subsequent agent action that installs or provisions the missing capability."
    },
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "A subsequent agent action operates on resources, artifacts, or values that were returned by an earlier observation, using them as its input.",
      "source_description": "An earlier observation that enumerates resources or produces artifacts, paths, or values.",
      "target_description": "A subsequent agent action that consumes those resources, artifacts, or values as its input."
    },
    {
      "name": "DERIVES_DECISION_FROM_OBSERVED_CONTENT",
      "definition": "The agent inspects document or artifact content obtained in an earlier observation and uses that content to reach a classification or field-extraction decision about the document.",
      "source_description": "An earlier observation containing content extracted from a document or artifact.",
      "target_description": "An agent decision that classifies the document or extracts specific fields from the observed content."
    }
  ]
}

